package com.slotmind.exception;
import org.springframework.dao.DataIntegrityViolationException; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.http.converter.HttpMessageNotReadableException; import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(ApiExceptions.NotFound.class) ResponseEntity<?> notFound(ApiExceptions.NotFound e){return ResponseEntity.status(404).body(Map.of("error",e.getMessage()));} @ExceptionHandler(ApiExceptions.Conflict.class) ResponseEntity<?> conflict(ApiExceptions.Conflict e){return ResponseEntity.status(409).body(Map.of("error",e.getMessage()));} @ExceptionHandler(DataIntegrityViolationException.class) ResponseEntity<?> integrity(){return ResponseEntity.status(409).body(Map.of("error","The operation conflicts with an existing record"));} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<?> invalid(MethodArgumentNotValidException e){return ResponseEntity.badRequest().body(Map.of("error","Invalid request","details",e.getBindingResult().getFieldErrors().stream().map(x->x.getField()+": "+x.getDefaultMessage()).toList()));} @ExceptionHandler(HttpMessageNotReadableException.class) ResponseEntity<?> unreadable(){return ResponseEntity.badRequest().body(Map.of("error","Malformed request body"));} @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<?> illegal(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));} }